import re,glob,collections
c=collections.Counter()
for f in glob.glob('features/**/*.*',recursive=True):
    if f.endswith(('.html','.ts')):
        s=open(f).read()
        for m in re.finditer(r'<app-pill(?=[\s/>])(.*?)(/?>)',s,re.S):
            for a in re.finditer(r'([\[\(]?[\w.-]+[\]\)]?)\s*=\s*("[^"]*"|\'[^\']*\')',m.group(1)):
                n=a.group(1)
                if n in('label','[label]'):c[n+' '+('lit' if n=='label' else a.group(2))[:40]]+=0
                else:c[n+' = '+a.group(2)]+=1
            c['END '+m.group(2)+ s[m.end():m.end()+12].replace('\n','\\n')[:10]]+=1
for k,v in sorted(c.items()):print(v,k)
